//! The committed demo CSV (`examples/demo-recipients.testnet.csv`, generated by
//! `cargo run -p drop-zcash --example demo_recipients`) is safe to commit and plays well with
//! the product: it imports cleanly with the real Zcash codec, fits one batch, and raises no
//! privacy warning.

use drop_core::{
    import_csv_str, plan_batches, privacy_warnings, standard_batch_fee, FeePolicy, ImportOptions,
};
use drop_zcash::{zcash_network, ZcashAddressCodec};

const CSV: &str = include_str!("../../../examples/demo-recipients.testnet.csv");

#[test]
fn demo_csv_holds_public_testnet_addresses_only() {
    let lower = CSV.to_ascii_lowercase();
    // No viewing or spending keys of any encoding, and nothing seed-like.
    for needle in [
        "uview",
        "uivk",
        "zxview",
        "zxsk",
        "secret-extended",
        "xprv",
        "tprv",
        "seed",
    ] {
        assert!(!lower.contains(needle), "CSV must not contain {needle:?}");
    }
    let longest_hex_run = CSV
        .split(|c: char| !c.is_ascii_hexdigit())
        .map(str::len)
        .max()
        .unwrap_or(0);
    assert!(
        longest_hex_run < 64,
        "no 32-byte hex blobs (seed-like) in the CSV"
    );

    let mut lines = CSV.lines();
    assert_eq!(lines.next(), Some("address,amount,memo"));
    for line in lines {
        assert!(line.starts_with("utest1"), "testnet Unified Addresses only");
    }
}

#[test]
fn demo_csv_imports_cleanly_into_one_varied_batch() {
    let codec = ZcashAddressCodec::new(zcash_network(drop_core::Network::Testnet));
    let rows = import_csv_str(CSV, &codec, &ImportOptions::default())
        .into_result()
        .expect("the demo CSV imports without errors");
    assert_eq!(rows.len(), 8);
    let total: u64 = rows.iter().map(|r| r.amount().as_u64()).sum();
    assert_eq!(total, 500_000, "exactly 0.005 TAZ");

    let batches = plan_batches(&rows, 50).unwrap();
    assert_eq!(batches.len(), 1);
    assert!(
        privacy_warnings(&batches).is_empty(),
        "{:?}",
        privacy_warnings(&batches)
    );

    // 8 Ironwood actions + 1 logical transparent action, at 5,000 zat each.
    let fee = standard_batch_fee(&FeePolicy::zip317_text(), 8).unwrap();
    assert_eq!(fee.as_u64(), 45_000);
}
